<script setup lang="ts">
import { computed } from 'vue'
import { newId, type Flow, type ProjectAction } from '../lib/model'
import TranslatableInput from './TranslatableInput.vue'
const props=defineProps<{actions:ProjectAction[];flows:Flow[];disabled?:boolean}>()
const emit=defineEmits<{ 'update:actions':[actions:ProjectAction[]] }>()
const icons=['Activity','AlertCircle','Check','CircleDot','Download','FileText','FolderOpen','Link2','Play','Power','RefreshCcw','Save','Search','Settings','SquareStop','Trash2','X','Zap']
const triggers=computed(()=>props.flows.flatMap(flow=>flow.nodes.filter(node=>node.kind==='trigger.ui').map(node=>({flow,node}))))
function update(index:number,patch:Partial<ProjectAction>){const next=props.actions.map((item,i)=>i===index?{...item,...patch}:item);emit('update:actions',next)}
function updateAction(index:number,patch:Partial<ProjectAction['action']>){const old=props.actions[index]!;update(index,{action:{...old.action,...patch}})}
function add(){emit('update:actions',[...props.actions,{id:newId('action'),text:{i18nKey:'',fallback:'新动作'},icon:'',shortcut:'',enabled:true,visible:true,action:{kind:'flow',flowId:'',entryNodeId:''}}])}
function remove(index:number){emit('update:actions',props.actions.filter((_,i)=>i!==index))}
function selectFlow(index:number,value:string){const [flowId,entryNodeId]=value.split(':');updateAction(index,{flowId:flowId??'',entryNodeId:entryNodeId||undefined})}
</script>
<template><section class="property-section action-editor"><h4>共享动作</h4><p class="muted-copy">按钮、菜单和工具栏可以调用同一个动作配置。</p><article v-for="(item,index) in actions" :key="item.id" class="action-card"><strong data-project-text>{{ item.id }}</strong><label>标题<TranslatableInput :model-value="item.text" @update:model-value="update(index,{text:$event})"/></label><div class="property-grid"><label>图标<select :value="item.icon ?? ''" @change="update(index,{icon:($event.target as HTMLSelectElement).value||undefined})"><option value="">无图标</option><option v-for="icon in icons" :key="icon" :value="icon">{{icon}}</option></select></label><label>快捷键<input :value="item.shortcut ?? ''" placeholder="Ctrl+Shift+R" @change="update(index,{shortcut:($event.target as HTMLInputElement).value})"/></label></div><label>动作流程<select :value="item.action.flowId ? `${item.action.flowId}:${item.action.entryNodeId ?? ''}` : ''" @change="selectFlow(index,($event.target as HTMLSelectElement).value)"><option value="">选择界面事件入口</option><option v-for="entry in triggers" :key="entry.node.id" :value="`${entry.flow.id}:${entry.node.id}`">{{entry.flow.name}} / {{entry.node.label}}</option></select></label><label>动作类型<select :value="item.action.kind" @change="updateAction(index,{kind:($event.target as HTMLSelectElement).value as any})"><option value="flow">执行指定流程</option><option value="startFlow">启动流程</option><option value="stopFlow">停止流程</option></select></label><label class="checkbox-label"><input type="checkbox" :checked="item.enabled!==false" @change="update(index,{enabled:($event.target as HTMLInputElement).checked})">启用</label><label class="checkbox-label"><input type="checkbox" :checked="item.visible!==false" @change="update(index,{visible:($event.target as HTMLInputElement).checked})">可见</label><button class="text-button" @click="remove(index)">删除动作</button></article><button class="text-button" :disabled="disabled" @click="add">＋ 添加共享动作</button></section></template>
<style scoped>.action-card{border:1px solid var(--line);border-radius:6px;padding:9px;margin:8px 0}.action-card>strong{font-size:10px;color:#78828d;overflow-wrap:anywhere}.action-card label{margin-top:8px}.action-card>.checkbox-label{display:flex;flex-direction:row;align-items:center}.action-card>.checkbox-label input{width:14px}.action-card .property-grid{gap:6px}</style>
